Store LinkedListNode references in the dictionary so moving and removing are O(1).
```csharp
public class LruCache<K, V>(int capacity) where K : notnull {
    private readonly Dictionary<K, LinkedListNode<(K Key, V Val)>> _map = new();
    private readonly LinkedList<(K Key, V Val)> _list = new();
    public bool TryGet(K key, out V val) {
        if (!_map.TryGetValue(key, out var n)) { val = default!; return false; }
        _list.Remove(n); _list.AddFirst(n); val = n.Value.Val; return true;
    }
    public void Put(K key, V val) {
        if (_map.TryGetValue(key, out var n)) _list.Remove(n);
        else if (_map.Count == capacity) { _map.Remove(_list.Last!.Value.Key); _list.RemoveLast(); }
        _map[key] = _list.AddFirst((key, val)); }
}
```

