```csharp
public class FixedWindowLimiter(int limit, TimeSpan window, IClock clock) : IRateLimiter {
    private class Window { public DateTime Start; public int Count; }
    private readonly ConcurrentDictionary<string, Window> _windows = new();
    public bool TryAcquire(string key) {
        var w = _windows.GetOrAdd(key, _ => new Window { Start = clock.UtcNow });
        lock (w) {
            var now = clock.UtcNow;
            if (now - w.Start >= window) { w.Start = now; w.Count = 0; }
            if (w.Count >= limit) return false;
            w.Count++; return true;
        } }
}
```
The lock is per client, so different clients never block each other.

```csharp
public class TokenBucket {
    private readonly double _capacity, _ratePerSec; private readonly TimeProvider _time;
    private double _tokens; private long _last; private readonly object _lock = new();
    public TokenBucket(double capacity, double ratePerSec, TimeProvider time) {
        _capacity = _tokens = capacity; _ratePerSec = ratePerSec; _time = time;
        _last = time.GetTimestamp(); }
    public bool TryConsume(int n = 1) { lock (_lock) {
        var now = _time.GetTimestamp();
        _tokens = Math.Min(_capacity, _tokens + _time.GetElapsedTime(_last, now).TotalSeconds * _ratePerSec);
        _last = now;
        if (_tokens < n) return false; _tokens -= n; return true; } }
}
```

