```csharp
public class EventBus : IEventBus {
    private readonly ConcurrentDictionary<Type, List<Func<object, Task>>> _handlers = new();
    public void Subscribe<T>(Func<T, Task> handler) {
        var list = _handlers.GetOrAdd(typeof(T), _ => new());
        lock (list) list.Add(e => handler((T)e));
    }
    public async Task PublishAsync<T>(T evt) {
        if (!_handlers.TryGetValue(typeof(T), out var list)) return;
        Func<object, Task>[] snapshot; lock (list) snapshot = list.ToArray();
        foreach (var h in snapshot) await h(evt!);
    }
}
```
Publishing over a snapshot avoids 'collection modified' errors if a handler subscribes during publish.

