Lazy expiry checks the timestamp on read and deletes stale entries.
```csharp
public class KvStore<TKey, TValue> where TKey : notnull {
    private record Entry(TValue Value, DateTime? ExpiresAt);
    private readonly ConcurrentDictionary<TKey, Entry> _map = new();
    public void Put(TKey k, TValue v, TimeSpan? ttl = null) =>
        _map[k] = new Entry(v, ttl is null ? null : DateTime.UtcNow + ttl);
    public bool TryGet(TKey k, out TValue? v) {
        v = default;
        if (!_map.TryGetValue(k, out var e)) return false;
        if (e.ExpiresAt <= DateTime.UtcNow) { _map.TryRemove(k, out _); return false; }
        v = e.Value; return true;
    }
}
```

Dictionary for lookup, LinkedList for recency order.
```csharp
public class LruCache<K, V> where K : notnull {
    private readonly int _cap;
    private readonly Dictionary<K, LinkedListNode<(K Key, V Val)>> _map = new();
    private readonly LinkedList<(K Key, V Val)> _list = new();
    public LruCache(int cap) => _cap = cap;
    public bool TryGet(K k, out V v) {
        v = default!; if (!_map.TryGetValue(k, out var n)) return false;
        _list.Remove(n); _list.AddFirst(n); v = n.Value.Val; return true;
    }
    // Put: if exists remove old node; AddFirst; if Count > _cap remove _list.Last and its key.
}
```

